import { searchDocuments } from '../lib/discovery/search';
(function(){
 'use strict';
 const root=document.documentElement,base='/design-preview',edition=root.dataset.edition,view=root.dataset.view;
 const key='five-minutes-prototype-v1',url=new URL(location.href),$=id=>document.getElementById(id);
 let blocked=url.searchParams.get('storage')==='blocked',state={},storageOK=true,realCache,scaleCache,generation=0;
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const editions=['adult','teen'];
 const validIds=a=>Array.isArray(a)?a.filter(x=>typeof x==='string'&&x.length<100):[];
 try{if(blocked)throw Error('blocked');state=JSON.parse(localStorage.getItem(key)||'{}')||{};if(typeof state!=='object'||Array.isArray(state))state={};}catch(_){storageOK=false;state={};}
 state.saved=validIds(state.saved);state.read=validIds(state.read);
 if(!editions.includes(state.edition))delete state.edition;
 function storageMessage(){const el=$('storage-message');if(el&&!storageOK){el.hidden=false;el.textContent='Device storage is unavailable. Changes last for this visit; nothing is saved between pages.';}}
 function persist(){try{if(blocked)throw Error('blocked');localStorage.setItem(key,JSON.stringify(state));storageOK=true;return true;}catch(_){storageOK=false;storageMessage();return false;}}
 function status(text){const el=$('action-status')||$('preferences-status');if(el)el.textContent=text;}
 function appearance(){root.dataset.appearance=['light','dark'].includes(state.appearance)?state.appearance:'system';root.dataset.textSize=state.textSize==='large'?'large':'normal';root.dataset.activity=state.activity==='tokens'?'tokens':'modules';root.dataset.figure=state.figure==='none'?'none':'explain';}
 function bridge(){const el=$('preference-bridge');if(!el)return;el.hidden=!state.edition||state.edition===edition;if(!el.hidden){$('bridge-text').textContent=`You’re reading ${edition==='teen'?'Teen':'Adult'}. Your usual edition is ${state.edition==='teen'?'Teen':'Adult'}.`;$('bridge-return').textContent=`Return to ${state.edition==='teen'?'Teen':'Adult'}`;const peer=document.querySelector('.edition-control a[data-edition-choice="'+state.edition+'"]');if(peer){const target=new URL(peer.href);target.search=location.search;target.hash=location.hash;$('bridge-return').href=target.href;}$('bridge-make').textContent=`Make ${edition==='teen'?'Teen':'Adult'} my edition`;}}
 function updateMarkers(){document.querySelectorAll('[data-state-id]').forEach(el=>{const id=el.dataset.stateId,read=state.read.includes(id),saved=state.saved.includes(id);el.textContent=saved?'◆':read?'✓':'';el.setAttribute('aria-label',saved?(read?'Saved and read':'Saved'):read?'Read':'Unread');});document.querySelectorAll('[data-save-id]').forEach(el=>{const on=state.saved.includes(el.dataset.saveId);el.textContent=on?'Saved · remove':'Save this idea';el.setAttribute('aria-pressed',String(on));});document.querySelectorAll('[data-read-id]').forEach(el=>{const on=state.read.includes(el.dataset.readId);el.textContent=on?'Read · undo':'Mark as read';el.setAttribute('aria-pressed',String(on));});}
 function updateLinks(){const source=new URL(location.href);document.querySelectorAll('a[href]').forEach(a=>{const target=new URL(a.href,location.href);if(target.origin!==location.origin||!target.pathname.startsWith(base))return;const choosing=a.hasAttribute('data-edition-choice');const preserve=choosing?[...source.searchParams.keys()]:['catalogue','network','storage'];if(choosing)target.search='';preserve.forEach(k=>{if(source.searchParams.has(k))target.searchParams.set(k,source.searchParams.get(k));else target.searchParams.delete(k);});if(a.hasAttribute('data-edition-choice')&&source.hash)target.hash=source.hash;a.href=target.href;});}
 async function real(){if(!realCache)realCache=fetch(base+'/catalogue.json').then(r=>{if(!r.ok)throw Error('catalogue');return r.json();}).catch(e=>{realCache=undefined;throw e;});return realCache;}
 async function scale(){if(!scaleCache)scaleCache=fetch(base+'/scale.json').then(r=>{if(!r.ok)throw Error('scale');return r.json();}).catch(e=>{scaleCache=undefined;throw e;});return scaleCache;}
 const date=s=>new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Zurich',day:'numeric',month:'short',year:'numeric'}).format(new Date(s));
 function row(l,remove=false){const p=l[edition],path=l.synthetic?base+'/fixture?id='+encodeURIComponent(l.id):p.path;const extra=remove?`<button class="saved-remove" type="button" data-remove-id="${escape(l.id)}">Remove</button>`:'';return `<li class="lesson-row"><span class="state-gutter" data-state-id="${escape(l.id)}" aria-label="Unread"></span><a class="row-link" href="${escape(path)}"><span class="row-topic">${escape(l.topicLabel)} · ${escape(l.subtopicLabel)}</span><span class="row-title">${escape(p.title)}</span><span class="row-deck">${escape(p.description)}</span></a><span class="row-date">${escape(date(l.publishedAt))}${l.synthetic?'<span class="prototype-note">Synthetic</span>':''}</span>${extra}</li>`;}
 async function saved(){const el=$('saved-content');if(!el)return;try{const docs=await real(),entries=state.saved.map(id=>docs.find(d=>d.id===id)).filter(Boolean);el.innerHTML=entries.length?`<ul class="lesson-list">${entries.map(d=>row(d,true)).join('')}</ul>`:'<p class="empty-state">No saved ideas yet. Open a lesson and choose “Save this idea”.</p><a href="'+base+'/editions/'+edition+'">Find today’s idea →</a>';const missing=state.saved.length-entries.length;if(missing){const p=document.createElement('p');p.className='quiet';p.textContent=`${missing} saved item is unavailable in this snapshot. Its saved identity is retained.`;el.append(p);}updateMarkers();updateLinks();}catch(_){el.innerHTML='<p>Saved ideas could not be loaded. <button type="button" id="saved-retry">Try again</button></p>';$('saved-retry')?.addEventListener('click',saved);}}
 function searchContext(){const u=new URL(location.href);return{q:u.searchParams.get('q')||'',scale:u.searchParams.get('catalogue')||'real',network:u.searchParams.get('network')||'normal',page:Math.max(1,Math.min(417,Number(u.searchParams.get('page'))||1))};}
 async function search(){if(view!=='search')return;const mine=++generation,ctx=searchContext(),q=ctx.q.trim(),field=$('search-query'),results=$('search-results'),label=$('search-status');field.value=ctx.q;results.innerHTML='';$('search-retry').hidden=true;updateLinks();if(!q){label.textContent='Enter a word or an idea to begin.';return;}label.textContent='Looking for ideas…';try{if(ctx.network==='slow')await new Promise(r=>setTimeout(r,1200));if(ctx.network==='error')throw Error('simulated');const docs=ctx.scale==='real'?await real():(await scale()).slice(0,ctx.scale==='1000'?1000:10000);if(mine!==generation)return;const documents=docs.map(l=>({...l[edition],id:l.id,publishedAt:l.publishedAt,topicLabel:l.topicLabel,subtopicLabel:l.subtopicLabel,concepts:l.concepts||[]}));const byId=new Map(docs.map(l=>[l.id,l]));const found=searchDocuments(documents,q,docs.length).map(result=>byId.get(result.document.id));if(!found.length){label.textContent='No ideas found. Try a broader word, or explore a topic.';results.innerHTML='<a href="'+base+'/editions/'+edition+'/topics">Explore Topics →</a>';return;}const total=Math.ceil(found.length/24),page=Math.min(ctx.page,total),slice=found.slice((page-1)*24,page*24);label.textContent=`${found.length} ${found.length===1?'idea':'ideas'} found${ctx.scale!=='real'?' in the synthetic fixture':''}.`;let pager='';if(total>1){const link=p=>{const u=new URL(location.href);u.searchParams.set('page',String(p));return escape(u.pathname+u.search);};pager=`<nav class="pagination" aria-label="Search result pages">${page>1?`<a data-search-page href="${link(page-1)}">← Previous</a>`:''}<span>Page ${page} of ${total}</span>${page<total?`<a data-search-page href="${link(page+1)}">Next →</a>`:''}</nav>`;}results.innerHTML=(ctx.scale!=='real'?'<p class="fixture-notice">Synthetic records for layout and interaction testing. These are not published lessons.</p>':'')+`<ul class="lesson-list">${slice.map(l=>row(l)).join('')}</ul>`+pager;updateMarkers();updateLinks();}catch(_){if(mine!==generation)return;label.textContent='Search could not load. Try again, or browse the Library.';$('search-retry').hidden=false;results.innerHTML='<a href="'+base+'/editions/'+edition+'/library">Browse the Library →</a>';}}
 function bindReview(id,keyName,initial){const select=$(id);if(!select)return;select.value=initial;select.addEventListener('change',()=>{if(keyName==='activity'||keyName==='figure'||keyName==='first'){state[keyName]=select.value;persist();appearance();firstVisit();return;}const u=new URL(location.href);u.searchParams.set(keyName,select.value);if(keyName==='catalogue')u.searchParams.delete('page');if(keyName==='storage'){location.replace(u.pathname+u.search+u.hash);return;}history.replaceState(null,'',u.pathname+u.search+u.hash);updateLinks();if(view==='search')search();});}
 function firstVisit(){const el=$('first-visit');if(!el)return;el.hidden=edition!=='adult'||!!state.edition||!!state.dismissed;const heading=el.querySelector('h2');if(heading)heading.textContent=state.first==='choice'?'Which voice suits you?':'Two voices. One idea.';}
 $('bridge-make')?.addEventListener('click',()=>{state.edition=edition;persist();bridge();firstVisit();});
 document.addEventListener('click',async event=>{const target=event.target instanceof Element?event.target.closest('a,button'):null;if(!target)return;
  if(target.hasAttribute('data-edition-choice')){const chosen=target.getAttribute('data-edition-choice');if(editions.includes(chosen)){state.edition=chosen;persist();}}
  if(target.hasAttribute('data-save-id')){const id=target.getAttribute('data-save-id');state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];const ok=persist();updateMarkers();status(ok?(state.saved.includes(id)?'Saved on this device.':'Removed from Saved.'):'Saved state changed for this visit only.');}
  if(target.hasAttribute('data-read-id')){const id=target.getAttribute('data-read-id');state.read=state.read.includes(id)?state.read.filter(x=>x!==id):[...state.read,id];persist();updateMarkers();status('Read marker updated.');}
  if(target.hasAttribute('data-remove-id')){state.saved=state.saved.filter(x=>x!==target.getAttribute('data-remove-id'));persist();saved();}
  if(target.hasAttribute('data-share')){const link=location.origin+location.pathname;try{if(navigator.share)await navigator.share({title:document.title,url:link});else if(navigator.clipboard){await navigator.clipboard.writeText(link);status('Lesson link copied.');}else status('Use the lesson link below to copy or bookmark.');}catch(e){if(e?.name!=='AbortError')status('Use the lesson link below to copy or bookmark.');}}
  if(target.hasAttribute('data-surprise')){event.preventDefault();try{const featured=document.querySelector('[data-featured-id]')?.dataset.featuredId;const docs=(await real()).filter(l=>l.id!==featured);if(docs.length)location.href=docs[Math.floor(Math.random()*docs.length)][edition].path;else location.href=target.href;}catch(_){location.href=target.href;}}
  if(target.hasAttribute('data-search-page')){event.preventDefault();history.pushState(null,'',target.href);search();$('search-form').scrollIntoView({block:'start'});}
 });
 document.querySelectorAll('[data-prediction-id]').forEach(input=>input.addEventListener('change',()=>{if(!input.checked)return;$('prediction-selected').textContent='You chose: '+input.closest('label').querySelector('span').textContent;$('prediction-reveal').open=true;}));
 $('dismiss-first')?.addEventListener('click',()=>{state.dismissed=true;persist();firstVisit();});
 $('preferences-form')?.addEventListener('change',()=>{state.appearance=$('appearance').value;state.textSize=$('text-size').value;appearance();const ok=persist();$('preferences-status').textContent=ok?'Preferences saved on this device.':'Preferences changed for this visit only.';});
 if($('appearance'))$('appearance').value=['light','dark'].includes(state.appearance)?state.appearance:'system';
 if($('text-size'))$('text-size').value=state.textSize==='large'?'large':'normal';
 $('search-form')?.addEventListener('submit',event=>{event.preventDefault();const u=new URL(location.href);const q=$('search-query').value;u.searchParams.set('q',q);u.searchParams.delete('page');history.pushState(null,'',u.pathname+u.search);search();});
 $('search-retry')?.addEventListener('click',()=>{const u=new URL(location.href);u.searchParams.delete('network');history.replaceState(null,'',u.pathname+u.search);$('review-network').value='normal';search();});
 window.addEventListener('popstate',()=>{updateLinks();search();});
 bindReview('review-activity','activity',state.activity==='tokens'?'tokens':'modules');bindReview('review-figure','figure',state.figure==='none'?'none':'explain');bindReview('review-first','first',state.first==='choice'?'choice':'offer');bindReview('review-scale','catalogue',url.searchParams.get('catalogue')||'real');bindReview('review-network','network',url.searchParams.get('network')||'normal');bindReview('review-storage','storage',blocked?'blocked':'normal');
 $('review-clear')?.addEventListener('click',()=>{try{localStorage.removeItem(key);}catch(_){}location.href=base;});
 $('review-mismatch')?.addEventListener('click',()=>{state.edition=edition==='adult'?'teen':'adult';persist();bridge();firstVisit();});
 $('review-rename')?.addEventListener('click',async()=>{try{const docs=await real(),entry=docs.find(l=>l.slug==='goodharts-law');state.saved=[...new Set([...state.saved,entry.id])];state.legacySavedSlug='old-goodhart-title';persist();updateMarkers();if(view==='saved')saved();status('Seeded by immutable ID; current title and URL are resolved from the catalogue.');}catch(_){status('Fixture could not load.');}});
 $('review-long')?.addEventListener('click',()=>{const h=document.querySelector('h1[data-original-title]');if(!h)return;if(h.dataset.stress){h.textContent=h.dataset.originalTitle;delete h.dataset.stress;}else{h.textContent='Synthetic title: what happens when a very long headline must fit a narrow screen with ease';h.dataset.stress='1';}});
 $('review-sparse')?.addEventListener('click',()=>{if(!$('earlier-sparse'))return;const show=$('earlier-sparse').hidden;$('earlier-sparse').hidden=!show;$('earlier-real').hidden=show;});
 appearance();bridge();firstVisit();storageMessage();updateMarkers();updateLinks();root.classList.add('enhanced');if(view==='saved')saved();if(view==='search')search();
})();
